import { Component, OnInit } from '@angular/core';
import { Router } from '@angular/router';
import { AlertController, ModalController, NavController } from '@ionic/angular';
import { AlertService } from 'src/app/services/alert.service';
import { EmisService } from 'src/app/services/emis/emis.service';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';
import { TeApplyExamPage } from '../te-apply-exam/te-apply-exam.page';
import { TeAppliedExamPage } from '../te-applied-exam/te-applied-exam.page';

@Component({
  selector: 'app-te-school-list',
  templateUrl: './te-school-list.page.html',
  styleUrls: ['./te-school-list.page.scss'],
})
export class TeSchoolListPage implements OnInit {

  emis_username: any;
  schoolList: any = [];
  ClassList: any = [];
  studentList: any = [];
  isSchool: boolean = true;
  schlName: any;
  isStudent: boolean;
  isClass: boolean;
  isDashboard:boolean;
  classId: any;
  menuList: any = [];
  studName: any;
  TalentExamMaster: any;
  studentData: any;

  constructor(
    public navCtrl: NavController,
    public alertCtrl:AlertController,
    private router: Router,
    private userService: UserService,
    private usersessionService: UserSessionService,
    private emisService: EmisService,
    private alertService: AlertService,
    private modalCtrl: ModalController,
  ) 
  {}

  ngOnInit() {
  }

  ionViewDidEnter(){
    this.emis_username = this.usersessionService.emis_username();
    this.getSchoolList();
  }

  getSchoolList(){
    let params = {
          "UserId" : this.emis_username
    }
    this.emisService.SRPWiseSchoolList(params).subscribe(res =>{
      if(res.dataStatus){
        this.schoolList = res.result.SRPSchoolStudList;
        this.TalentExamMaster = res.result.TalentExamMaster;
        
      }else{
        this.alertService.error(res.message);
      }
    })
  }

  onSchool(data){
    this.ClassList = data.ClassList;
    this.schlName = data.school_name;
    this.isSchool = false;
    this.isStudent = false;
    this.isClass = true;
    this.isDashboard = false;
  }

  onClass(data){
    this.isClass = false;
    this.isSchool = false;
    this.isDashboard = false;
    this.isStudent = true;
    this.studentList = data.StudentList;
    this.classId = data.class_id;
    // console.log("Selected Class", data);
  }

  onStudent(data){
    this.isClass = false;
    this.isStudent = false;
    this.isSchool = false;
    this.isDashboard = true;
    this.studName = data.name;
    this.menuList = [
      {
        id: 1,
        title: "Apply Exam",
        image: "assets/icons/classroomStrategies.svg",
        url: "",
        studData: data,
      },
      {
        id: 2,
        title: "Applied Exam",
        image: "assets/icons/learning.svg",
        url: "",
        studData: data,
      }
    ]
    // this.router.navigate(['/tabs/talent-exam-dahsboard'], {queryParams:{StudId: data.StudId, ClassId: data.class_studying_id, SchlId: data.class_studying_id }});
    // console.log("Selected Class", data);
  }

  async onSelect(item){
    // console.log("Selected Class", item.studData);
    if(item.id == 1){
      const modal = await this.modalCtrl.create({
        component: TeApplyExamPage,
        componentProps: { data: item.studData, exam: this.TalentExamMaster },
        cssClass: 'te-exam-modal'
      });
      await modal.present();
      const { data, role } = await modal.onWillDismiss();
      if (data == 1) {
        this.SRPWiseSchoolList(item.studData);
      }
    }
    if(item.id == 2){
      const modal = await this.modalCtrl.create({
        component: TeAppliedExamPage,
        componentProps: { data: item.studData, exam: this.TalentExamMaster },
        cssClass: 'te-exam-modal'
      });
      await modal.present();
      const { data, role } = await modal.onWillDismiss();
      if (data == 2) {
        this.SRPWiseSchoolList(item.studData);
      }
    }
  }

  navigateSchool(){
    this.isSchool = true;
    this.isClass = false;
    this.isStudent = false;
    this.isDashboard = false;
  }

  navigateClass(){
    this.isClass = true;
    this.isSchool = false;
    this.isStudent = false;
    this.isDashboard = false;
  }

  navigateStudent(){
    this.isClass = false;
    this.isSchool = false;
    this.isStudent = true;
    this.isDashboard = false;
  }
  
  navigateBack() {
    this.router.navigate(['/tabs/stem-dashboard']);
  }

  SRPWiseSchoolList(data){
    let params = {
      "UserId" : this.emis_username
    }
    this.emisService.SRPWiseSchoolList(params).subscribe(res =>{
      if(res.dataStatus){
        this.schoolList = res.result.SRPSchoolStudList;
        this.TalentExamMaster = res.result.TalentExamMaster;

        let schoolData = this.schoolList.filter(dd => dd.school_id == data.school_id);
        this.ClassList = schoolData[0].ClassList;
        let classData = this.ClassList.filter(dd => dd.class_id == data.class_studying_id);
        this.studentList = classData[0].StudentList;
        let studData = this.studentList.filter(dd => dd.StudId == data.StudId);
        this.studentData = studData[0];
        this.onStudent(this.studentData);
      }else{
        this.alertService.error(res.message);
      }
    })
  }

}
